<template>
  <div class="sl-root">
    <main class="sl-body">
      <section class="sl-card">
        <!-- ── Card header ──────────────────────────────────────────── -->
        <div class="sl-card__head">
          <div class="sl-card__head-left">
            <div class="sl-card__chip">HR</div>
            <h2 class="sl-card__title">District Study Leave Register</h2>
          </div>
          <div class="sl-card__head-right">
            <span class="sl-card__sub" v-if="isHR && !loading">
              {{ filteredLeaves.length }} of {{ studyLeaves.length }} records
            </span>
          </div>
        </div>

        <!-- ── Loading / access check ──────────────────────────────── -->
        <div v-if="!accessChecked || (accessChecked && isHR && loading)" class="sl-loading">
          <v-progress-circular indeterminate color="primary" size="48"></v-progress-circular>
          <span>{{ !accessChecked ? 'Verifying access…' : 'Loading study leave records…' }}</span>
        </div>

        <!-- ── Access denied ───────────────────────────────────────── -->
        <div v-else-if="!isHR" class="pa-6">
          <v-alert type="error" outlined prominent border="left">
            <v-row align="center">
              <v-col class="grow">
                <div class="font-weight-bold text-h6 mb-1">Access Restricted</div>
                <div>
                  This module is only accessible to District HR personnel. Your
                  account does not have the required HR role.
                </div>
              </v-col>
              <v-col class="shrink">
                <v-icon size="48" color="error">mdi-lock-outline</v-icon>
              </v-col>
            </v-row>
          </v-alert>
        </div>

        <template v-else>
          <!-- ── Filters ─────────────────────────────────────────────── -->
          <v-card-text class="pb-1 pt-3">
            <v-row dense>
              <v-col cols="12" sm="6" md="3">
                <v-text-field
                  v-model="filter.name"
                  label="Search staff name"
                  dense
                  outlined
                  hide-details
                  clearable
                  prepend-inner-icon="mdi-magnify"
                  class="ma-1"
                  @input="onFilterChange"
                  @click:clear="onFilterChange"
                />
              </v-col>

              <v-col cols="12" sm="6" md="2">
                <v-select
                  v-model="filter.trainingType"
                  :items="trainingTypeOptions"
                  label="Training type"
                  dense
                  outlined
                  hide-details
                  clearable
                  prepend-inner-icon="mdi-school"
                  class="ma-1"
                  @change="onFilterChange"
                  @click:clear="onFilterChange"
                />
              </v-col>

              <v-col cols="12" sm="6" md="2">
                <v-select
                  v-model="filter.outcome"
                  :items="outcomeOptions"
                  label="Completion status"
                  dense
                  outlined
                  hide-details
                  clearable
                  prepend-inner-icon="mdi-flag-checkered"
                  class="ma-1"
                  @change="onFilterChange"
                  @click:clear="onFilterChange"
                />
              </v-col>

              <v-col cols="12" sm="6" md="3">
                <v-autocomplete
                  v-model="filter.facility"
                  :items="facilityOptions"
                  label="Facility"
                  dense
                  outlined
                  hide-details
                  clearable
                  prepend-inner-icon="mdi-hospital-building"
                  class="ma-1"
                  @change="onFilterChange"
                  @click:clear="onFilterChange"
                />
              </v-col>

              <v-col cols="12" sm="auto" class="d-flex align-center">
                <v-btn
                  v-if="hasActiveFilters"
                  text
                  small
                  color="red darken-1"
                  class="ma-1"
                  @click="resetFilters"
                >
                  <v-icon small left>mdi-close</v-icon>
                  Clear filters
                </v-btn>
              </v-col>
            </v-row>
          </v-card-text>

          <!-- ── Error banner ────────────────────────────────────────── -->
          <v-alert
            v-if="loadError"
            type="warning"
            dense
            outlined
            class="mx-4 mb-2"
          >
            {{ loadError }}
          </v-alert>

          <!-- ── Data table ──────────────────────────────────────────── -->
          <v-data-table
            :headers="tableHeaders"
            :items="filteredLeaves"
            :items-per-page="15"
            :footer-props="{
              'items-per-page-options': [10, 15, 25, 50],
              'items-per-page-text': 'Rows per page',
            }"
            no-data-text="No study leave records match the current filters"
            class="elevation-0"
            @click:row="viewStudyLeave"
          >
            <!-- Staff name -->
            <template #[`item.staffName`]="{ item }">
              <div class="sl-table__primary">{{ item.staffName }}</div>
            </template>

            <!-- Course -->
            <template #[`item.course`]="{ item }">
              <span class="sl-table__muted">{{ item.course }}</span>
            </template>

            <!-- Facility -->
            <template #[`item.facility`]="{ item }">
              <span class="sl-table__muted">{{ item.facility }}</span>
            </template>

            <!-- Training dates -->
            <template #[`item.dateRange`]="{ item }">
              <span class="sl-table__muted">{{ item.dateRange }}</span>
            </template>

            <!-- Training type chip -->
            <template #[`item.trainingTypeDisplay`]="{ item }">
              <v-chip
                v-if="item.trainingType"
                x-small
                :color="typeColor(item.trainingType)"
                dark
              >
                {{ item.trainingTypeDisplay }}
              </v-chip>
              <span v-else class="sl-table__muted">—</span>
            </template>

            <!-- Completion status chip -->
            <template #[`item.outcome`]="{ item }">
              <span
                class="sl-status-pill"
                :class="'sl-status-pill--' + outcomeKey(item.outcome)"
              >
                <span class="sl-status-pill__dot"></span>
                {{ outcomeLabel(item.outcome) }}
              </span>
            </template>

            <!-- Row actions -->
            <template #[`item.actions`]="{ item }">
              <v-menu offset-y>
                <template #activator="{ on, attrs }">
                  <v-btn icon small v-bind="attrs" v-on="on" @click.stop>
                    <v-icon small>mdi-dots-vertical</v-icon>
                  </v-btn>
                </template>
                <v-list dense>
                  <v-list-item @click="viewStudyLeave(item)">
                    <v-list-item-icon class="mr-2">
                      <v-icon small>mdi-eye-outline</v-icon>
                    </v-list-item-icon>
                    <v-list-item-title>View Study Leave</v-list-item-title>
                  </v-list-item>
                  <v-list-item @click="updateCompletion(item)">
                    <v-list-item-icon class="mr-2">
                      <v-icon small>mdi-pencil-outline</v-icon>
                    </v-list-item-icon>
                    <v-list-item-title>Update Completion Status</v-list-item-title>
                  </v-list-item>
                </v-list>
              </v-menu>
            </template>
          </v-data-table>
        </template>
      </section>
    </main>

    <v-snackbar v-model="snackbar.show" :color="snackbar.color" top right :timeout="4000">
      {{ snackbar.text }}
      <template #action="{ attrs }">
        <v-btn text v-bind="attrs" @click="snackbar.show = false">Close</v-btn>
      </template>
    </v-snackbar>
  </div>
</template>

<script>
import generalMixin from "../../mixins/general";

const STUDY_LEAVE_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/study-leave-profile";
const POSITION_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/position-profile";

export default {
  name: "StudyLeaveList",
  mixins: [generalMixin],
  props: ["queries"],

  data() {
    return {
      accessChecked: false,
      isHR: false,
      allowedFacilities: [],

      loading: true,
      loadError: null,
      studyLeaves: [],

      filter: {
        name: "",
        trainingType: null,
        outcome: null,
        facility: null,
      },
      filterDebounce: null,
      filteredLeaves: [],

      trainingTypeOptions: [
        { text: "Long-Term", value: "longterm" },
        { text: "Short-Term", value: "shortterm" },
        { text: "Part-Time", value: "parttime" },
      ],

      // Loaded from the FHIR ValueSet at runtime
      outcomeValueSetItems: [],

      tableHeaders: [
        { text: "", value: "actions", sortable: false, width: "52px" },
        { text: "Staff Name", value: "staffName", width: "200px" },
        { text: "Facility", value: "facility" },
        { text: "Course / Program", value: "course" },
        { text: "Type", value: "trainingTypeDisplay", sortable: false },
        { text: "Training Dates", value: "dateRange", sortable: false },
        { text: "Completion Status", value: "outcome", sortable: false },
      ],

      snackbar: { show: false, text: "", color: "success" },
    };
  },

  computed: {
    facilityOptions() {
      return this.allowedFacilities.map((f) => ({
        text: f.name,
        value: f.name,
      }));
    },

    outcomeOptions() {
      const dynamic = this.outcomeValueSetItems.map((item) => ({
        text: item.display || item.code,
        value: item.code,
      }));
      return [{ text: "Not Recorded", value: "__none__" }, ...dynamic];
    },

    hasActiveFilters() {
      return (
        !!this.filter.name ||
        !!this.filter.trainingType ||
        !!this.filter.outcome ||
        !!this.filter.facility
      );
    },
  },

  async mounted() {
    await this.$nextTick();

    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (v) => {
        if (!v) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        console.warn("Timeout waiting for user data");
        resolve();
      }, 15000);
    });

    await this.checkAccess();

    if (this.isHR) {
      // Load outcome value set and study leave data in parallel
      await Promise.all([
        this.loadOutcomeValueSet(),
        this.loadStudyLeaves(),
      ]);
    } else {
      this.loading = false;
    }
  },

  methods: {
    // ── Value set loading ─────────────────────────────────────────────
    async loadOutcomeValueSet() {
      try {
        const items = await this.$fhirutils.expand(
          "http://ihris.org/fhir/ValueSet/training-outcome-valueset",
        );
        this.outcomeValueSetItems = items || [];
      } catch (err) {
        console.error("loadOutcomeValueSet error:", err);
      }
    },

    // ── Access control ────────────────────────────────────────────────
    async checkAccess() {
      try {
        const practitionerId =
          this.loggedInStaff && this.loggedInStaff.practitioner;
        if (!practitionerId) {
          this.accessChecked = true;
          return;
        }

        const resp = await fetch("/site/general/getHR/" + practitionerId);
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        const hrList = await resp.json();

        const matched = Array.isArray(hrList)
          ? hrList.find((h) =>
              h.practitioners.find((p) => p === practitionerId),
            )
          : null;

        if (!matched) {
          this.isHR = false;
          this.accessChecked = true;
          return;
        }

        this.isHR = true;
        this.allowedFacilities = Array.isArray(matched.coverage)
          ? matched.coverage.map((f) => ({ id: f.id, name: f.name }))
          : [];
      } catch (err) {
        console.error("checkAccess error:", err);
        this.isHR = false;
      } finally {
        this.accessChecked = true;
      }
    },

    // ── Data loading ──────────────────────────────────────────────────
    async loadStudyLeaves() {
      this.loading = true;
      this.loadError = null;
      try {
        if (this.allowedFacilities.length === 0) {
          this.studyLeaves = [];
          this.applyFilters();
          return;
        }

        // Step 1: fetch positions at the HR's facilities, reverse-including PractitionerRoles
        const facilityParam = this.allowedFacilities
          .map((f) => `Location/${f.id}`)
          .join(",");

        const posRes = await fetch(
          `/fhir/Basic?_profile=${POSITION_PROFILE}` +
            `&facility=${facilityParam}` +
            `&_count=1000` +
            `&_revinclude=PractitionerRole:roleposition`,
        );
        const posBundle = await posRes.json();
        const entries = posBundle.entry || [];

        // Build position → facility name map
        const positionFacilityMap = {};
        for (const e of entries) {
          const r = e.resource;
          if (!r?.meta?.profile?.some((p) => p.includes("position-profile")))
            continue;
          const facExt = (r.extension || []).find((x) =>
            x.url.includes("facility"),
          );
          const facRef = facExt?.valueReference?.reference;
          if (facRef) {
            const facId = String(facRef.split("/")[1]);
            const fac = this.allowedFacilities.find(
              (f) => String(f.id) === facId,
            );
            if (fac) positionFacilityMap[`Basic/${r.id}`] = fac.name;
          }
        }

        // Extract practitioner references from PractitionerRole entries
        const practitionerRefs = new Set();
        const practitionerFacilityMap = {};

        for (const e of entries) {
          const r = e.resource;
          if (r?.resourceType !== "PractitionerRole") continue;

          const practRef = r.practitioner?.reference;
          if (!practRef) continue;
          practitionerRefs.add(practRef);

          // Try to find the position this role links to for the facility name
          // PractitionerRole in iHRIS may store the position ref in an extension
          const posRef =
            (r.extension || []).find((x) => x.url.includes("position"))
              ?.valueReference?.reference ||
            (r.code || [])
              .flatMap((c) => c.coding || [])
              .find((c) => c.system?.includes("position"))?.code;

          if (posRef && positionFacilityMap[posRef]) {
            practitionerFacilityMap[practRef] = positionFacilityMap[posRef];
          }
        }

        if (practitionerRefs.size === 0) {
          this.studyLeaves = [];
          this.applyFilters();
          return;
        }

        // Step 2: fetch study leaves for those practitioners
        const practParam = Array.from(practitionerRefs).join(",");
        const slRes = await fetch(
          `/fhir/Basic?_profile=${STUDY_LEAVE_PROFILE}` +
            `&practitioner=${practParam}` +
            `&_count=500`,
        );
        const slBundle = await slRes.json();
        const slEntries = slBundle.entry || [];

        if (slEntries.length === 0) {
          this.studyLeaves = [];
          this.applyFilters();
          return;
        }

        // Step 3: batch-load practitioner names
        const uniquePractRefs = [
          ...new Set(
            slEntries
              .map((e) => {
                const exts = e.resource?.extension || [];
                return exts.find((x) =>
                  x.url.includes("ihris-practitioner-reference"),
                )?.valueReference?.reference;
              })
              .filter(Boolean),
          ),
        ];

        const practNameMap = {};
        await Promise.all(
          uniquePractRefs.map(async (ref) => {
            try {
              const r = await fetch(`/fhir/${ref}?_elements=name`);
              const pract = await r.json();
              const name = pract.name?.[0];
              practNameMap[ref] = name
                ? `${name.given?.join(" ") || ""} ${name.family || ""}`.trim()
                : ref;
            } catch {
              practNameMap[ref] = ref;
            }
          }),
        );

        // Step 3b: batch-load date ranges for all linked leave requests
        const uniqueLeaveRefs = [
          ...new Set(
            slEntries.flatMap((e) =>
              (e.resource?.extension || [])
                .filter((x) => x.url.includes("leave-request-reference"))
                .map((x) => x.valueReference?.reference)
                .filter(Boolean),
            ),
          ),
        ];

        const leaveDatesMap = {};
        await Promise.all(
          uniqueLeaveRefs.map(async (ref) => {
            try {
              const id = ref.split("/")[1];
              const r = await fetch(`/fhir/Basic/${id}`);
              const lr = await r.json();
              const lrExts = lr.extension || [];
              leaveDatesMap[ref] = {
                startDate: lrExts.find((x) => x.url.includes("start-date"))
                  ?.valueDate,
                endDate: lrExts.find((x) => x.url.includes("end-date"))
                  ?.valueDate,
              };
            } catch {
              leaveDatesMap[ref] = {};
            }
          }),
        );

        // Step 4: build table rows
        this.studyLeaves = await Promise.all(
          slEntries.map(async (e) => {
            const r = e.resource;
            const exts = r.extension || [];
            const getExt = (part) => exts.find((x) => x.url.includes(part));

            const practRef = getExt("ihris-practitioner-reference")
              ?.valueReference?.reference;
            const typeCoding = getExt("training-type")?.valueCoding;

            // Completion outcome
            const completionExt = exts.find((x) =>
              x.url.includes("training-completion"),
            );
            const outcome =
              completionExt?.extension?.find((x) =>
                x.url.includes("training-outcome"),
              )?.valueCoding?.code || null;

            // Facility: prefer the map built from PractitionerRole, fall back to allowedFacilities
            const facility =
              practitionerFacilityMap[practRef] ||
              (this.allowedFacilities.length === 1
                ? this.allowedFacilities[0].name
                : "—");

            // Course/Program: fall back to the linked qualification's name
            const course =
              getExt("planning-course")?.valueString ||
              (await this.resolveQualificationName(r)) ||
              "—";

            // Training dates: span across all linked leave requests
            const leaveRefs = exts
              .filter((x) => x.url.includes("leave-request-reference"))
              .map((x) => x.valueReference?.reference)
              .filter(Boolean);

            const dates = leaveRefs
              .map((ref) => leaveDatesMap[ref])
              .filter((d) => d && (d.startDate || d.endDate));

            const startDates = dates.map((d) => d.startDate).filter(Boolean);
            const endDates = dates.map((d) => d.endDate).filter(Boolean);

            const earliestStart = startDates.length
              ? startDates.reduce((a, b) => (a < b ? a : b))
              : null;
            const latestEnd = endDates.length
              ? endDates.reduce((a, b) => (a > b ? a : b))
              : null;

            const dateRange =
              earliestStart || latestEnd
                ? `${this.formatDate(earliestStart)} – ${this.formatDate(latestEnd)}`
                : "—";

            return {
              id: r.id,
              practitioner: practRef ? practRef.split("/")[1] : null,
              staffName: practNameMap[practRef] || "Unknown",
              facility,
              course,
              institution: getExt("planning-institution")?.valueString || "—",
              trainingType: typeCoding?.code || "",
              trainingTypeDisplay:
                typeCoding?.display || typeCoding?.code || "—",
              dateRange,
              outcome,
            };
          }),
        );

        this.applyFilters();
      } catch (err) {
        console.error("loadStudyLeaves error:", err);
        this.loadError =
          "Some records could not be loaded. Showing partial results.";
      } finally {
        this.loading = false;
      }
    },

    // ── Filtering ─────────────────────────────────────────────────────
    applyFilters() {
      const name = (this.filter.name || "").toLowerCase().trim();
      const type = this.filter.trainingType;
      const outcome = this.filter.outcome;
      const facility = this.filter.facility;

      this.filteredLeaves = this.studyLeaves.filter((row) => {
        if (name && !row.staffName.toLowerCase().includes(name)) return false;
        if (type && row.trainingType !== type) return false;
        if (outcome) {
          if (outcome === "__none__" && row.outcome !== null) return false;
          if (outcome !== "__none__" && row.outcome !== outcome) return false;
        }
        if (facility && row.facility !== facility) return false;
        return true;
      });
    },

    onFilterChange() {
      clearTimeout(this.filterDebounce);
      this.filterDebounce = setTimeout(() => this.applyFilters(), 250);
    },

    resetFilters() {
      this.filter = { name: "", trainingType: null, outcome: null, facility: null };
      this.applyFilters();
    },

    // ── Navigation ────────────────────────────────────────────────────
    viewStudyLeave(item) {
      this.$router.push({
        path: "/custom/study-leave-view",
        query: {
          path: "/lesotho/components/training",
          id: item.id,
          returnLabel: "Back to Register",
        },
      });
    },

    updateCompletion(item) {
      this.$router.push({
        path: "/custom/training-completion",
        query: {
          path: "/lesotho/components/training",
          id: item.id,
          practitioner: item.practitioner,
        },
      });
    },

    // ── Display helpers ───────────────────────────────────────────────
    typeColor(type) {
      return (
        { longterm: "blue darken-1", shortterm: "purple darken-1", parttime: "green darken-1" }[type] || "grey"
      );
    },

    outcomeLabel(outcome) {
      if (!outcome) return "Not Recorded";
      const item = this.outcomeValueSetItems.find((i) => i.code === outcome);
      return item ? item.display || item.code : outcome;
    },

    outcomeKey(outcome) {
      // Colour semantics — drive from code regardless of display text
      const map = { completed: "done", failed: "error", ongoing: "active" };
      return map[outcome] || "none";
    },

    outcomeColor(outcome) {
      const map = { completed: "success", failed: "error", ongoing: "blue" };
      return map[outcome] || "grey";
    },

    formatDate(dateString) {
      if (!dateString) return "—";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric",
      });
    },

    // ── Resolve qualification/course display name ──────────────────────
    async resolveQualificationName(resource) {
      const qualNameOtherExt = resource.extension?.find((e) =>
        e.url.endsWith("/qualification-name-other"),
      );
      if (qualNameOtherExt?.valueString) return qualNameOtherExt.valueString;

      const qualNameExt = resource.extension?.find((e) =>
        e.url.endsWith("/qualification-name"),
      );
      if (qualNameExt?.valueReference?.display) {
        return qualNameExt.valueReference.display;
      }

      const ref = qualNameExt?.valueReference?.reference;
      if (!ref) return null;

      try {
        const id = ref.split("/")[1];
        const response = await fetch(`/fhir/Basic/${id}`);
        if (!response.ok) return null;

        const qualification = await response.json();
        return qualification.extension?.find((e) =>
          e.url.endsWith("/ihris-basic-name"),
        )?.valueString;
      } catch (error) {
        console.error("Error resolving qualification name:", error);
        return null;
      }
    },
  },
};
</script>

